window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["model-selection"]={"title":"模型选型与成本：寻找满足约束的最小可行方案","subtitle":"从任务分布、强模型上界和多维门禁，到每成功任务成本、帕累托前沿与退出策略。","thesis":"模型选型不是找榜单冠军，而是在代表性任务上先满足质量、安全、隐私和延迟硬约束，再从可行候选中最小化生命周期成本。真正的经济指标是<b>每个成功任务的完整成本与失败损失</b>，不是单次调用或 token 单价。","quality":{"contractVersion":2,"examples":[{"section":5,"evidence":{"setup":"处理 1000 笔退款","rule":"先筛硬约束，再比较完整经济性","steps":"¥151/900=¥0.168","interpretation":"人工单价或流量结构改变，结论也会改变"}}],"formulas":[{"id":"model-selection-constrained","section":3,"formulaIndex":1,"symbols":[{"name":"m","meaning":"候选模型与配套配置","evidence":"输入候选 m"},{"name":"TotalCost","meaning":"候选的生命周期总成本","evidence":"总成本 TotalCost"},{"name":"Quality","meaning":"候选在第 k 个质量维度的结果","evidence":"各质量 Qualityk"},{"name":"k","meaning":"质量约束索引","evidence":"第 k 项质量下限"},{"name":"Q","meaning":"质量下限","evidence":"Qk 是第 k 项质量下限"},{"name":"Risk","meaning":"候选在第 j 个风险维度的结果","evidence":"风险 Riskj"},{"name":"j","meaning":"风险约束索引","evidence":"第 j 项风险上限"},{"name":"R","meaning":"风险上限","evidence":"Rj 是第 j 项风险上限"},{"name":"P95","meaning":"候选的第九十五百分位延迟","evidence":"延迟 P95"},{"name":"L","meaning":"允许的延迟上限","evidence":"L 是延迟上限"},{"name":"Privacy","meaning":"候选的数据与隐私类别","evidence":"隐私类别 Privacy"},{"name":"C","meaning":"允许的隐私类别集合","evidence":"C 是允许的隐私类别集合"}]},{"id":"model-selection-cost-per-success","section":4,"formulaIndex":1,"symbols":[{"name":"CostPerSuccess","meaning":"每个真实成功任务的完整成本","evidence":"完整成本 CostPerSuccess"},{"name":"Ccall","meaning":"模型调用成本","evidence":"调用 Ccall"},{"name":"Ctool","meaning":"检索与工具成本","evidence":"检索工具 Ctool"},{"name":"Cretry","meaning":"重试与升级成本","evidence":"重试升级 Cretry"},{"name":"Chuman","meaning":"人工处理成本","evidence":"人工 Chuman"},{"name":"Cinfra","meaning":"基础设施成本","evidence":"基础设施 Cinfra"},{"name":"Closs","meaning":"失败造成的损失","evidence":"失败损失 Closs"},{"name":"Nsuccess","meaning":"独立确认的成功任务数","evidence":"成功任务数 Nsuccess"}]},{"id":"model-selection-availability","section":8,"formulaIndex":1,"symbols":[{"name":"Asystem","meaning":"串行链路的近似系统可用率","evidence":"系统可用率 Asystem"},{"name":"i","meaning":"串行依赖编号","evidence":"第 i 个依赖"},{"name":"A","meaning":"第 i 个依赖的可用率","evidence":"依赖的可用率 Ai"}]}],"termReviews":[{"term":"强模型上界","section":2,"evidence":"强模型基线输入冻结评测集"},{"term":"帕累托前沿","section":3,"evidence":"进入帕累托前沿"},{"term":"每成功任务成本","section":4,"evidence":"输出每成功任务完整成本"}],"sectionContracts":[{"section":1,"definition":{"answer":"模型选型是在业务硬约束内寻找最小生命周期成本方案。","evidence":"模型选型输入任务分布、成功定义"},"problem":{"answer":"它解决不同任务无法共享一个排行榜结论的问题。","evidence":"为什么不能共享同一排行榜结论"},"inputOutput":{"answer":"输入分布门槛和预算，输出满足约束的候选配置集合。","evidence":"输出满足全部硬约束的候选配置集合"},"mechanism":{"answer":"先定义成功与不可补偿门槛，再比较候选。","evidence":"先定义“成功”和不可补偿门槛"},"interpretation":{"answer":"榜单分数只在任务与约束相同时才可比较。","evidence":"这些条件相同才可解释"},"boundary":{"answer":"硬约束失败不能被价格或普通样本高分抵消。","evidence":"不能被价格或普通样本高分抵消"}},{"section":2,"definition":{"answer":"强模型基线是当前架构在充分证据下的能力上界参照。","evidence":"先用强模型建立系统上界"},"problem":{"answer":"它区分模型能力不足与任务、数据、检索或工具问题。","evidence":"怎样判断是模型不够强还是检索、提示和流程有问题"},"inputOutput":{"answer":"输入冻结集和完整系统，输出质量上界及逐样本错误。","evidence":"输出当前系统架构可达到的质量上界及逐样本错误"},"mechanism":{"answer":"先跑强基线，再固定其余变量逐项替换做消融。","evidence":"一次只替换一个变量做消融"},"interpretation":{"answer":"oracle 下仍失败说明应先修系统定义或证据链。","evidence":"优先修任务、数据或工具"},"boundary":{"answer":"强模型上界是诊断参照，不是自动生产推荐。","evidence":"不是自动生产推荐"}},{"section":3,"definition":{"answer":"模型选型是带质量风险延迟隐私约束的成本最小化。","evidence":"选型是受约束的多目标优化"},"problem":{"answer":"它避免把不可补偿维度武断加成一个总分。","evidence":"怎样放进同一决策，而不武断加成一个总分"},"inputOutput":{"answer":"输入候选指标和门槛，输出可行域最低成本方案。","evidence":"输出可行域中总成本 TotalCost 最低的方案"},"mechanism":{"answer":"先筛硬门槛，再在可行候选中比较帕累托和成本。","evidence":"先执行硬门槛，再看帕累托和成本"},"interpretation":{"answer":"帕累托前沿表示未被全面支配，不等于自动胜出。","evidence":"不代表自动胜出"},"boundary":{"answer":"不满足任一硬约束的候选不进入经济性比较。","evidence":"Qk 是第 k 项质量下限"}},{"section":4,"definition":{"answer":"每成功任务成本汇总任务全链路成本并除以真实成功数。","evidence":"完整成本从请求流转而不是价目表计算"},"problem":{"answer":"它揭示低单次调用价格如何被重试、人工和失败反超。","evidence":"为什么可能更贵"},"inputOutput":{"answer":"输入全链路成本和成功数，输出每成功任务完整成本。","evidence":"输出每成功任务完整成本 CostPerSuccess"},"mechanism":{"answer":"分子汇总全部成本，分母只计独立确认的业务成功。","evidence":"分母只计真实业务成功"},"interpretation":{"answer":"调用便宜若增加人工和失败，最终方案仍可能更贵。","evidence":"低单次价格若带来更多人工和失败"},"boundary":{"answer":"难以定价的高风险不能货币化抵消，应保留硬门槛。","evidence":"无法定价的高风险应保留硬门槛"}},{"section":5,"definition":{"answer":"退款案例先筛三种模型的硬门槛再比较完整成本。","evidence":"便宜模型怎样输给较贵模型"},"problem":{"answer":"它验证单次价格最低不等于每成功任务成本最低。","evidence":"谁的每成功任务成本低"},"inputOutput":{"answer":"输入一千笔任务及三候选数据，输出可行者和单位成功成本。","evidence":"输出可行候选及每成功任务成本"},"mechanism":{"answer":"先淘汰越权与延迟失败者，再用完整成本除成功数。","evidence":"再计算 M 的 151÷900≈0.168 元"},"interpretation":{"answer":"M 只在当前人工价格和流量假设下胜出。","evidence":"它在当前假设胜出"},"boundary":{"answer":"成本或流量改变后必须重新做敏感性分析。","evidence":"必须重做敏感性分析"}},{"section":6,"definition":{"answer":"供应商与运行方式共同构成一个可治理的模型候选。","evidence":"供应商与运行方式也是候选的一部分"},"problem":{"answer":"它处理质量相近端点在合同版本容量和退出上的差异。","evidence":"为什么合同、版本与退出能力会决定结果"},"inputOutput":{"answer":"输入行为合同和退出证据，输出运行方案与替代路径。","evidence":"输出可治理的运行方案与替代路径"},"mechanism":{"answer":"通过合同审查和真实切换演练验证治理与恢复能力。","evidence":"实际切换恢复时间才是退出能力证据"},"interpretation":{"answer":"接口一致不能推导格式拒答或分词行为一致。","evidence":"接口相同不保证格式、拒答和 tokenization 相同"},"boundary":{"answer":"自托管同样必须计运维、补丁、许可和值班。","evidence":"自托管也必须计入运维、补丁和值班成本"}},{"section":7,"definition":{"answer":"静态模型组合按组件难度和风险分配不同执行者。","evidence":"一个应用可静态组合多个模型"},"problem":{"answer":"它避免让单一大模型承担权限、抽取和所有高风险步骤。","evidence":"为什么常常不是最终系统设计"},"inputOutput":{"answer":"输入组件需求，输出规则、各级模型或人工职责分工。","evidence":"输出规则、小模型、中模型、强模型或人工的职责分工"},"mechanism":{"answer":"对每个组件固定责任、接口和独立验收门槛。","evidence":"让权限检查、抽取和高风险判断分别验收"},"interpretation":{"answer":"组合收益来自系统分工，不能全归因于某个模型。","evidence":"不能把路由收益误记为底层模型能力"},"boundary":{"answer":"动态路由必须作为后续独立系统另行评测。","evidence":"动态路由是后续独立系统"}},{"section":8,"definition":{"answer":"回退链为模型或依赖失败预定义替代动作与预算。","evidence":"回退、降级和退出必须进入评测"},"problem":{"answer":"它说明首选超时或非法输出时用户实际经历的路径。","evidence":"用户实际经历什么"},"inputOutput":{"answer":"输入失败信号和依赖可用率，输出回退分支及系统可用率。","evidence":"输出重试、升级、确定性代码、询问、人工或失败分支以及系统可用率"},"mechanism":{"answer":"按错误类型选择分支，并用依赖乘积估算串行可用率。","evidence":"可用率近似各 Ai 的乘积"},"interpretation":{"answer":"单组件高可用不代表串行端到端链路同样可用。","evidence":"端到端仍会下降"},"boundary":{"answer":"相关故障、副作用和总延迟必须做故障注入。","evidence":"必须通过故障注入验证"}},{"section":9,"definition":{"answer":"模型选择是随价格版本分布政策和风险变化的生命周期决策。","evidence":"选择会过期，需要触发复评"},"problem":{"answer":"它防止团队把采购时结论永久沿用到变化后的系统。","evidence":"为什么下个月可能不再可行"},"inputOutput":{"answer":"输入各类变化信号，输出复评、灰度切换或退出决定。","evidence":"输出继续使用、重新比较、灰度切换或退出决定"},"mechanism":{"answer":"触发器出现即重跑冻结集、真实抽样并更新决策卡。","evidence":"并更新决策卡"},"interpretation":{"answer":"历史最优只对当时的数据、成本和约束假设成立。","evidence":"历史最优只对当时数据和假设成立"},"boundary":{"answer":"任何旧结论都不能绕过当前门禁自动继承。","evidence":"不能永久继承"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>把选型写成约束优化；计算每成功任务成本；理解强模型基线与受控消融；用帕累托前沿和切片门槛决策。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>“哪个模型最好”缺少目标函数<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">抽取发票、写文案和批准退款，为什么不能共享同一排行榜结论？</p><p>三类任务的正确性定义、错误代价、上下文、输出结构和权限完全不同。先定义输入分布、成功事件、高风险切片、延迟 SLO、数据边界、吞吐与预算；只有这些条件固定，模型分数才成为可比较证据。</p><p>退款助手的硬门槛可包括：越权率≤0.5%、质量问题资格准确率≥90%、p95≤1.8s、数据不得跨指定区域。普通解释清晰度和成本则是可优化目标。硬约束失败的模型不能靠更低价格“补回来”。</p><div class=\"dd-note\"><b>选型问题：</b>在约束集合 C 内，哪个模型—提示—工具配置的长期总成本最小？模型名字只是方案的一部分。</div><p>模型选型输入任务分布、成功定义、风险切片、SLO、数据边界和预算，输出满足全部硬约束的候选配置集合。先定义“成功”和不可补偿门槛，再比较候选；榜单分数只有在这些条件相同才可解释。任何硬约束失败都不能被价格或普通样本高分抵消。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>先用强模型建立系统上界<span class=\"dd-badge eng\">诊断</span></h2><p class=\"dd-lead\">原型表现差时，怎样判断是模型不够强还是检索、提示和流程有问题？</p><p>先用能力强、上下文充分、工具稳定的候选跑代表性样本，得到当前架构上界。若 oracle 证据下强模型仍失败，应修任务定义、数据、工具或验收；若强模型通过，再逐项换小模型、减少上下文和推理预算，测每个节省造成的损失。</p><ol class=\"dd-steps\"><li>冻结评测集和评分器，不边比较边改题。</li><li>强模型 + 完整证据建立可达上界。</li><li>固定其余变量，只替换一个模型或推理配置。</li><li>保留逐样本差异，检查新旧错误迁移。</li><li>再评端到端回退链，而非只测单次输出。</li></ol><div class=\"dd-note warn\"><b>强模型基线不是默认生产方案。</b>　它是诊断参照；隐私、延迟或许可也可能让它从一开始就不可行。</div><p>强模型基线输入冻结评测集、充分证据和稳定工具，输出当前系统架构可达到的质量上界及逐样本错误。若强模型在 oracle 证据下仍失败，优先修任务、数据或工具；若它通过，再一次只替换一个变量做消融。上界是诊断参照，不是自动生产推荐。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>选型是受约束的多目标优化<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">质量、风险、延迟和成本怎样放进同一决策，而不武断加成一个总分？</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"模型选型的受约束优化\"><munder><mi>min</mi><mi>m</mi></munder><mi>TotalCost</mi><mo>(</mo><mi>m</mi><mo>)</mo><mo>,</mo><mi>s.t.</mi><msub><mi>Quality</mi><mi>k</mi></msub><mo>(</mo><mi>m</mi><mo>)</mo><mo>≥</mo><msub><mi>Q</mi><mi>k</mi></msub><mo>,</mo><msub><mi>Risk</mi><mi>j</mi></msub><mo>(</mo><mi>m</mi><mo>)</mo><mo>≤</mo><msub><mi>R</mi><mi>j</mi></msub><mo>,</mo><mi>P95</mi><mo>(</mo><mi>m</mi><mo>)</mo><mo>≤</mo><mi>L</mi><mo>,</mo><mi>Privacy</mi><mo>(</mo><mi>m</mi><mo>)</mo><mo>∈</mo><mi>C</mi></math></div><p>先用门槛筛可行域，再看成本、吞吐和维护负担。若多个目标没有公认换算率，用帕累托前沿：不存在另一个候选在所有维度不差且至少一项更好。处于前沿不等于自动胜出，只说明值得结合业务权重讨论。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>维度</th><th>建议表达</th><th>不能被什么抵消</th></tr></thead><tbody><tr><td>关键质量</td><td>切片通过率与区间</td><td>普通样本平均提升</td></tr><tr><td>安全/权限</td><td>事件率与严重度</td><td>更自然的文风</td></tr><tr><td>延迟</td><td>TTFT、p95/p99、超时</td><td>平均延迟</td></tr><tr><td>成本</td><td>每成功任务与峰值容量</td><td>token 单价</td></tr><tr><td>治理</td><td>地域、保留、审计、退出能力</td><td>模型能力分</td></tr></tbody></table></div><p>约束优化输入候选 m、各质量 Qualityk、风险 Riskj、延迟 P95、隐私类别 Privacy 与门槛，输出可行域中总成本 TotalCost 最低的方案。Qk 是第 k 项质量下限，Rj 是第 j 项风险上限，L 是延迟上限，C 是允许的隐私类别集合。先执行硬门槛，再看帕累托和成本；进入帕累托前沿只表示未被全面支配，不代表自动胜出。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>完整成本从请求流转而不是价目表计算<span class=\"dd-badge math\">经济性</span></h2><p class=\"dd-lead\">小模型单次只要大模型的四分之一，为什么可能更贵？</p><p>一次任务可能包含初答、检索、重试、升级强模型、工具、人工复核和失败补救。固定成本还包括部署冗余、监控、评测、供应商集成和迁移。把这些都归到成熟业务结果上。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"每成功任务完整成本\"><mi>CostPerSuccess</mi><mo>=</mo><mfrac><mrow><mi>Ccall</mi><mo>+</mo><mi>Ctool</mi><mo>+</mo><mi>Cretry</mi><mo>+</mo><mi>Chuman</mi><mo>+</mo><mi>Cinfra</mi><mo>+</mo><mi>Closs</mi></mrow><mi>Nsuccess</mi></mfrac></math></div><p>失败损失不一定能精确定价，高风险通常用硬门槛更诚实；但至少要显示人工和重试，否则会奖励把成本转嫁给运营团队的方案。</p><div class=\"dd-note warn\"><b>分母陷阱：</b>若只统计系统宣称完成的任务，会漏掉用户放弃和错误自动批准；成功必须由独立业务状态定义。</div><p>成本核算输入调用 Ccall、检索工具 Ctool、重试升级 Cretry、人工 Chuman、基础设施 Cinfra、失败损失 Closs 和独立确认的成功任务数 Nsuccess，输出每成功任务完整成本 CostPerSuccess。分子汇总任务全链路资源与损失，分母只计真实业务成功；低单次价格若带来更多人工和失败，最终可能更贵。无法定价的高风险应保留硬门槛。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>运行示例：便宜模型怎样输给较贵模型<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">处理 1000 笔退款，单次 ¥0.02 的 S 与 ¥0.08 的 M，谁的每成功任务成本低？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 700 250\" role=\"img\" aria-label=\"三个模型候选经过硬门槛筛选和每成功任务成本比较\"><defs><marker id=\"ms1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"20\" y=\"52\" width=\"145\" height=\"142\" rx=\"9\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"92\" y=\"77\" text-anchor=\"middle\" class=\"svg-t\">候选 S / M / L</text><text x=\"92\" y=\"102\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">同一评测集与工具</text><text x=\"92\" y=\"124\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">记录质量/风险/延迟</text><text x=\"92\" y=\"146\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">记录重试/人工/失败</text><path d=\"M165,123 L238,123\" stroke=\"#6b7484\" marker-end=\"url(#ms1)\"/><rect x=\"240\" y=\"52\" width=\"160\" height=\"142\" rx=\"9\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"320\" y=\"77\" text-anchor=\"middle\" class=\"svg-t\">硬门槛筛选</text><text x=\"320\" y=\"103\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">S：越权 0.8% → 淘汰</text><text x=\"320\" y=\"126\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">M：全部通过</text><text x=\"320\" y=\"149\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">L：延迟 2.4s → 淘汰</text><text x=\"320\" y=\"172\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">不可用总分互相补偿</text><path d=\"M400,123 L474,123\" stroke=\"#6b7484\" marker-end=\"url(#ms1)\"/><rect x=\"476\" y=\"52\" width=\"204\" height=\"142\" rx=\"9\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"578\" y=\"77\" text-anchor=\"middle\" class=\"svg-t\">可行域内比较</text><text x=\"578\" y=\"103\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">M：¥151 / 900 成功</text><text x=\"578\" y=\"126\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">≈ ¥0.168 / 成功任务</text><text x=\"578\" y=\"149\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">保留回退与复评计划</text><text x=\"578\" y=\"172\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">不是永久冠军</text></svg><figcaption>图 1　先筛硬约束，再比较完整经济性；便宜但越权的候选不会进入成本赛道。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>候选</th><th>单次调用</th><th>成功率</th><th>人工率×¥1</th><th>失败补救</th><th>每成功任务</th></tr></thead><tbody><tr><td>S 小模型</td><td>¥20</td><td>78%=780</td><td>180×1=¥180</td><td>40×¥3=¥120</td><td>(20+180+120)/780=¥0.410</td></tr><tr><td>M 中模型</td><td>¥80</td><td>90%=900</td><td>65×1=¥65</td><td>2×¥3=¥6</td><td>¥151/900=¥0.168</td></tr><tr><td>L 强模型</td><td>¥180</td><td>93%=930</td><td>35×1=¥35</td><td>1×¥3=¥3</td><td>¥218/930=¥0.234</td></tr></tbody></table></div><p>S 虽调用最便宜，总成本最高且若越权率超过硬门槛应直接淘汰。M 在给定假设下胜出；人工单价或流量结构改变，结论也会改变，所以要做敏感性分析。</p><p>案例输入 1000 笔退款及 S、M、L 三个候选的门槛、调用、成功、人工和补救数据，输出可行候选及每成功任务成本。先淘汰越权或延迟不合格者，再计算 M 的 151÷900≈0.168 元；它在当前假设胜出，但人工单价和流量变化后必须重做敏感性分析。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>供应商与运行方式也是候选的一部分<span class=\"dd-badge eng\">治理</span></h2><p class=\"dd-lead\">两个端点输出质量相近时，为什么合同、版本与退出能力会决定结果？</p><p>比较数据是否用于训练、保留期、区域、加密、审计、模型版本锁定、速率限制、SLA、批量价格、内容政策和停服条款。自托管还要计 GPU 利用、补丁、值班和灾备。开源权重允许控制却不自动给出许可、数据来源或安全保证。</p><p>做退出演练：导出提示与评测、切换备用端点、验证输出契约和工具兼容，测实际恢复时间。供应商“等价模型”可能在格式、拒答和 tokenization 上不同；抽象接口只能降低迁移成本，不能消除行为差异。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>问题</th><th>需要的证据</th></tr></thead><tbody><tr><td>能否锁版本</td><td>快照标识、变更通知和回归窗口</td></tr><tr><td>数据去向</td><td>合同、地域、保留和子处理方</td></tr><tr><td>容量保证</td><td>配额、突发策略、SLA 与故障记录</td></tr><tr><td>退出成本</td><td>替代端点实测、迁移脚本和兼容差异</td></tr></tbody></table></div><p>供应商评估输入模型行为、合同、地域、保留期、版本、容量、许可和退出演练，输出可治理的运行方案与替代路径。接口相同不保证格式、拒答和 tokenization 相同；实际切换恢复时间才是退出能力证据。自托管也必须计入运维、补丁和值班成本。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>一个应用可静态组合多个模型<span class=\"dd-badge eng\">架构</span></h2><p class=\"dd-lead\">“选一个模型”为什么常常不是最终系统设计？</p><p>意图分类、查询改写、核心推理、代码执行和安全复核的难度与风险不同，可按组件静态分工。例如确定性规则先检查权限，小模型抽取订单字段，中模型解释政策，高风险异常转人工。这样比让一个大模型承担所有步骤更可测。</p><p>动态路由则在请求级预测难度再选模型，可能进一步省成本，但引入错误下放、级联延迟和路由器漂移。应先建立静态基线，确认每个组件门槛，再把路由作为独立系统评测；不能把路由收益归功于底层模型。</p><div class=\"dd-note warn\"><b>工具不是模型能力的免费加成。</b>　不同候选对 schema、错误恢复和上下文的利用不同，必须在同一端到端工具链实测。</div><p>静态模型组合输入各组件的难度、风险、结构与工具需求，输出规则、小模型、中模型、强模型或人工的职责分工。按组件固定责任能让权限检查、抽取和高风险判断分别验收；动态路由是后续独立系统，不能把路由收益误记为底层模型能力。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>回退、降级和退出必须进入评测<span class=\"dd-badge eng\">可靠性</span></h2><p class=\"dd-lead\">首选模型超时、限流、低置信或输出非法时，用户实际经历什么？</p><p>预先定义：重试同端点、升级强模型、改用确定性代码、请求补充信息、返回缓存、转人工或明确失败。每种分支有总 token、总延迟和副作用预算；首答内容不可无审查地塞给后续模型，以免错误或注入污染级联。</p><p>把故障注入评测：供应商 429、流中断、工具超时、schema 变化和区域不可用。测最终任务成功率、p95、重复动作和人工负载。主模型 99.9% 可用不代表完整级联相同可靠，依赖串联会降低端到端可用性。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"串行独立依赖的近似可用率\"><mi>Asystem</mi><mo>≈</mo><munder><mo>∏</mo><mi>i</mi></munder><msub><mi>A</mi><mi>i</mi></msub></math></div><p>回退设计输入超时、限流、低置信、非法输出与第 i 个依赖的可用率 Ai，输出重试、升级、确定性代码、询问、人工或失败分支以及系统可用率 Asystem。串行独立依赖的可用率近似各 Ai 的乘积；它解释组件各自很可靠时端到端仍会下降。真实相关故障、重复副作用和总延迟必须通过故障注入验证。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>选择会过期，需要触发复评<span class=\"dd-badge intuition\">生命周期</span></h2><p class=\"dd-lead\">今天的最优模型为什么下个月可能不再可行？</p><p>价格、版本、上下文长度、供应商政策、流量语言、任务规则和人工成本都会变化。设置触发器：模型快照更新、价格变动、关键切片漂移、错误预算耗尽、新风险要求或备用切换失败。定期运行冻结集和真实抽样，而不是只在采购期比较一次。</p><p>记录决策卡：候选、排除原因、数据版本、门槛、区间、成本假设、审批人、复评日期和退出方案。避免团队忘记某候选为何因隐私或越权被淘汰，又仅凭新版榜单重新引入。</p><div class=\"dd-note warn\"><b>基准污染：</b>公开榜单只能提供候选，不能代替私有代表性集；反复针对同一私有集调参也会过拟合。</div><p>生命周期复评输入价格、模型版本、任务分布、政策、人工成本和错误预算变化，输出继续使用、重新比较、灰度切换或退出决定。触发器出现时重跑冻结集与真实抽样，并更新决策卡；历史最优只对当时数据和假设成立，不能永久继承。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">选型不是一次采购，而是一项可复现、可退出、会随环境变化的工程决策。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>总榜最高就是最好</td><td>任务分布、工具和硬约束决定可行性</td></tr><tr><td>单次调用便宜就是省钱</td><td>要算重试、人工、失败、容量后的每成功任务成本</td></tr><tr><td>强模型基线等于生产推荐</td><td>它用于建立上界和诊断，仍受隐私/延迟/成本约束</td></tr><tr><td>一个应用只能选一个模型</td><td>可静态分工或动态路由，但组合也需端到端评测</td></tr><tr><td>选定后长期不变</td><td>版本、价格、分布和规则变化都会使结论过期</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>模型评测、应用评测、概率与成本核算</td></tr><tr><td><b>本页核心</b></td><td>强基线、硬门槛、帕累托前沿、每成功任务成本、退出策略</td></tr><tr><td>架构</td><td>模型路由、推理优化、部署、提示缓存</td></tr><tr><td>生命周期</td><td>可观测性、数据漂移、供应商治理与人在回路</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>定义任务分布与硬约束</li><li>强模型建立架构上界</li><li>固定条件比较逐样本差异</li><li>筛除不满足门槛的候选</li><li>计算完整每成功任务成本</li><li>灰度发布并按触发器复评/退出</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么先用强模型建立上界？</li><li>每成功任务成本应包含什么？</li><li>帕累托前沿代表自动最优吗？</li><li>模型路由与静态选型差在哪？</li><li>哪些变化触发复评？</li><li>假设“模型选型与成本：寻找满足约束的最小可行方案”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“模型选型与成本：寻找满足约束的最小可行方案”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>帮助区分模型能力不足与数据、提示、工具或任务定义问题。</li><li>调用、检索工具、重试升级、人工、基础设施和失败补救。</li><li>不代表，只说明没有候选在所有维度支配它，仍需业务权重。</li><li>选型按项目/组件固定方案，路由按每个请求动态选择。</li><li>模型/价格/供应商政策、流量分布、任务规则、风险或故障表现变化。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2305.05176\" target=\"_blank\" rel=\"noopener\">FrugalGPT</a>：级联调用的成本与质量优化</li><li><a href=\"https://arxiv.org/abs/2406.18665\" target=\"_blank\" rel=\"noopener\">RouteLLM</a>：偏好数据驱动的模型路由</li><li><a href=\"https://arxiv.org/abs/2211.09110\" target=\"_blank\" rel=\"noopener\">HELM</a>：多场景、透明模型评测</li><li><a href=\"https://www.nist.gov/itl/ai-risk-management-framework\" target=\"_blank\" rel=\"noopener\">NIST AI RMF</a>：风险约束与生命周期治理</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
